WITH base AS (SELECT *, DATE_ADD(opened_date, 48) AS opened_date_plus_48d, CAST(sqft AS STRING) AS sqft_str, COALESCE(region, 'OTHER') AS resolved_region FROM stores WHERE region = 'West') SELECT id, region, opened_date, sqft, opened_date_plus_48d, sqft_str, resolved_region, COUNT(sqft) OVER w_ordered AS region_count_sqft, MIN(sqft) OVER w_ordered AS region_min_sqft FROM base WINDOW w_ordered AS (PARTITION BY region)
